st.markdown("---")

if not st.session_state.quiz_done:
    # 进度条
    progress = st.session_state.current_q / len(QUESTIONS)
    st.progress(progress)
    st.markdown(f'<p class="progress-text">Question {st.session_state.current_q + 1} of {len(QUESTIONS)}</p>', unsafe_allow_html=True)

    # 当前题目
    q_idx = st.session_state.current_q
    question = QUESTIONS[q_idx]

    st.markdown(f'<div class="question-box"><h3>{question["q"]}</h3></div>', unsafe_allow_html=True)

    # 选项按钮
    for i, (option_text, option_scores) in enumerate(question["options"]):
        if st.button(f"{'ABCD'[i]}. {option_text}", key=f"q{q_idx}_opt{i}", use_container_width=True):
            # 记录答案和分数
            st.session_state.answers.append(i)
            for j in range(5):
                st.session_state.scores[j] += option_scores[j]
            st.session_state.current_q += 1

            if st.session_state.current_q >= len(QUESTIONS):
                st.session_state.quiz_done = True

            st.rerun()

else:
    # ============ 答题完成，进行分院 ============
    scores = st.session_state.scores
    # 归一化到 1-10 范围
    max_possible = 30  # 大约每题最高3分 x 10题
    normalized = [max(1, min(10, int(s / max_possible * 10) + 3)) for s in scores]
    courage, ambition, loyalty, intelligence, bravery = normalized

    st.markdown("### 🔮 The Sorting Hat is deliberating...")

    user_input = np.array([[courage, ambition, loyalty, intelligence, bravery]])
    prediction = model.predict(user_input)[0]
    probabilities = model.predict_proba(user_input)[0]
    classes = model.classes_
    house_info = HOUSES[prediction]

    st.markdown(f'<div class="house-card {house_info["css"]}"><h2>{house_info["emoji"]} {prediction}!</h2><p>"You belong in {prediction}, where dwell the {house_info["trait"].lower()}!"</p></div>', unsafe_allow_html=True)

    st.markdown("<br>", unsafe_allow_html=True)

    # 你的得分
