    with c3: st.metric("🤝 Loyalty", f"{loyalty}/10")
    with c4: st.metric("📚 Intelligence", f"{intelligence}/10")
    with c5: st.metric("⚔️ Bravery", f"{bravery}/10")

    st.markdown("<br>", unsafe_allow_html=True)

    # 概率分布
    st.markdown("### 📊 Sorting Confidence")
    prob_df = pd.DataFrame({"House":[f"{HOUSES[c]['emoji']} {c}" for c in classes],"Probability":probabilities}).sort_values("Probability",ascending=True)
    fig = px.bar(prob_df, x="Probability", y="House", orientation="h", color="Probability", color_continuous_scale=["#333","#ffd700"], range_color=[0,1], text_auto=".1%")
    fig.update_layout(paper_bgcolor="rgba(0,0,0,0)",plot_bgcolor="rgba(0,0,0,0)",font_color="#e8d5b7",height=250,margin=dict(l=20,r=20,t=10,b=10),coloraxis_showscale=False,xaxis=dict(range=[0,1],gridcolor="rgba(255,215,0,0.1)"),yaxis=dict(gridcolor="rgba(0,0,0,0)"))
    st.plotly_chart(fig, use_container_width=True)

    # 雷达图
    st.markdown("### 🕸️ Your Trait Profile")
    cats = ["Courage","Ambition","Loyalty","Intelligence","Bravery"]
    vals = [courage,ambition,loyalty,intelligence,bravery]
