    fig_r = go.Figure(data=go.Scatterpolar(r=vals_closed,theta=cats+cats[:1],fill='toself',fillcolor='rgba(255,215,0,0.15)',line_color='#ffd700',line_width=3,marker_size=8))
    fig_r.update_layout(polar=dict(radialaxis=dict(visible=True,range=[0,10],gridcolor="rgba(255,215,0,0.2)"),angularaxis=dict(gridcolor="rgba(255,215,0,0.2)"),bgcolor="rgba(0,0,0,0)"),paper_bgcolor="rgba(0,0,0,0)",font_color="#e8d5b7",height=400,margin=dict(l=60,r=60,t=30,b=30),showlegend=False)
